"""Ciencias Naturales EPJA Básica N2, módulo 1, desempeño OAD-02: investigaciones sobre la estructura y la función de los sistemas digestivo y respiratorio, evaluando procedimientos y resultados. Todo en papel; datos de ejemplo."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = "Papel, lápiz y goma. Todo se resuelve con los datos de ejemplo escritos en la ficha: no se hace ningún experimento real. Si quieres contar tus respiraciones, hazlo solo sentado y en reposo, sin esfuerzo."
build = make_build(MATERIALS)

O2 = "EPJA-CNAT-NB2-OAD-02"
PRIOR = ["Sé que comemos para obtener energía y que respiramos aire.", "Conozco los niveles de organización: célula, tejido, órgano, sistema y organismo."]


def K(n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_):
    if len(op) == 5:  # (enunciado, ejemplo, criterios, evidencia, retroalimentación): los errores son los frecuentes de la clase
        op = (*op[:4], [m[0] for m in mistakes], op[4])
    build(O2, n, F, use=use, prior=PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc, op=op, reinforce=rf, extend=ex_)


